200: function recalibrateGroup(groupName,reason='PM requested a fresh ranking',rejectedFeature=''){
201:   const index=state.groups.findIndex(group=>group.name===groupName);if(index<0)return;
202:   const current=state.groups[index],before=current.requirements.map(r=>({id:r.id,feature:r.feature,rank:r.rank,score:r.score,status:r.status}));
203:   const rebuilt=buildModel(state.evidence,state.config,statusMap(),state.context,overrideMap());
204:   let replacement=rebuilt.find(group=>group.name===groupName);
205:   if(!replacement){
206:     const remainingFeatures=new Set(current.requirements.map(r=>r.feature).filter(feature=>feature!==rejectedFeature));
207:     const requirements=rebuilt.flatMap(group=>group.requirements).filter(r=>remainingFeatures.has(r.feature)).sort((a,b)=>b.score-a.score).slice(0,10);
208:     if(requirements.length)replacement={...current,requirements:requirements.map((r,position)=>({...r,group:groupName,rank:position+1}))};
209:   }
210:   if(replacement)state.groups.splice(index,1,replacement);else state.groups.splice(index,1);
211:   state.selected=Math.min(index,Math.max(0,state.groups.length-1));
212:   const after=replacement?.requirements.map(r=>({id:r.id,feature:r.feature,rank:r.rank,score:r.score,status:r.status}))||[];
213:   addEvent('group-recalibrated','Requirement group recalibrated',`${groupName}: ${reason}. ${before.length} → ${after.length} ranked requirements.`,{group:groupName,rejectedFeature,before,after});
214:   render();
215: }
