.hero-studio-card{margin-top:24px;border-radius:6px;overflow:hidden;background:rgba(10,24,38,.75);border:1px solid rgba(130,180,219,.22);box-shadow:0 16px 45px rgba(0,0,0,.45);backdrop-filter:blur(16px);transition:border-color .25s ease,transform .25s ease}
.hero-studio-card:hover{border-color:rgba(130,180,219,.42);transform:translateY(-2px)}
.hero-studio-media{position:relative;width:100%;height:220px;overflow:hidden}
.studio-preview-img{width:100%;height:100%;object-fit:cover;display:block}
.studio-badge{position:absolute;bottom:12px;left:14px;background:rgba(5,14,24,.88);backdrop-filter:blur(10px);color:#c4dcff;font-size:10px;font-weight:700;letter-spacing:.06em;padding:5px 12px;border-radius:20px;border:1px solid rgba(130,180,219,.3);display:flex;align-items:center;gap:8px;text-transform:uppercase}
.studio-meta{padding:12px 18px;display:flex;justify-content:space-between;gap:14px;font-size:11px;color:#8fa5b8;background:rgba(6,15,25,.92);border-top:1px solid rgba(130,180,219,.12);flex-wrap:wrap}
.studio-meta strong{color:#dce7f2;font-weight:650}

.cockpit-hud-pill{display:flex;align-items:center;gap:12px;padding:5px 12px;background:rgba(13,25,38,.85);border:1px solid rgba(130,180,219,.25);border-radius:4px;box-shadow:0 6px 18px rgba(0,0,0,.35);backdrop-filter:blur(12px)}
.hud-mini-thumb{width:40px;height:40px;object-fit:cover;border-radius:3px;border:1px solid rgba(130,180,219,.35);flex-shrink:0}
.hud-pill-info{display:flex;flex-direction:column;gap:2px}
.hud-status-text{display:flex;align-items:center;gap:6px;font-size:10px;font-weight:800;letter-spacing:.09em;color:#5ca7e6;text-transform:uppercase}
.hud-pill-info small{font-size:10px;color:#9bb1c5;white-space:nowrap}

.memory-visual-card,.market-visual-card{margin:20px 0;border-radius:6px;overflow:hidden;background:rgba(10,24,38,.8);border:1px solid rgba(130,180,219,.2);box-shadow:0 16px 45px rgba(0,0,0,.4);backdrop-filter:blur(14px)}
.memory-banner-img,.market-banner-img{width:100%;height:260px;object-fit:cover;display:block}
.memory-card-caption,.market-card-caption{padding:12px 20px;font-size:11px;color:#8fa5b8;background:rgba(6,15,25,.92);border-top:1px solid rgba(130,180,219,.15);display:flex;align-items:center;gap:10px}
.memory-card-caption strong,.market-card-caption strong{color:#dce7f2;text-transform:uppercase;letter-spacing:.07em;font-size:10px;font-weight:700}

