args.ReplacementContent:
@media(max-width:720px){
  .cockpit-hud-pill{display:none}
  .hero-studio-media{height:150px}
  .memory-banner-img,.market-banner-img{height:160px}
  .studio-meta{flex-direction:column;gap:4px}
}

/* 3D Penthouse Studio Spatial Navigation */
.penthouse-viewport{position:relative;width:100%;height:100vh;min-height:760px;overflow:hidden;perspective:1300px;perspective-origin:50% 50%;background:#040c14;display:flex;align-items:center;justify-content:center;transition:opacity .5s ease,visibility .5s ease}
.penthouse-viewport.hidden{display:none}
.penthouse-camera{position:relative;width:100%;height:100%;transform-style:preserve-3d;transition:transform .85s cubic-bezier(.22,1,.36,1);will-change:transform}

.penthouse-scene-layer{position:absolute;inset:-60px;transform:translateZ(-260px) scale(1.24);transform-origin:center center;pointer-events:none}
.penthouse-backdrop-img{width:100%;height:100%;object-fit:cover;display:block;filter:brightness(.9) contrast(1.08)}
.penthouse-lighting-overlay{position:absolute;inset:0;background:radial-gradient(circle at 50% 48%,rgba(0,35,70,.2) 0%,rgba(4,12,20,.62) 68%,rgba(4,12,20,.95) 100%)}

.penthouse-stations-layer{position:absolute;inset:0;transform-style:preserve-3d;pointer-events:none}
.penthouse-station{position:absolute;pointer-events:auto;cursor:pointer;transform-style:preserve-3d;outline:none;user-select:none}

/* Station Positioning */
.station-center{left:50%;top:57%;transform:translate(-50%,-50%) translateZ(40px);width:320px}
.station-left{left:18%;top:45%;transform:translate(-50%,-50%) translateZ(25px) rotateY(16deg);width:330px}
.station-right{left:82%;top:43%;transform:translate(-50%,-50%) translateZ(20px) rotateY(-18deg);width:330px}
.station-desk{left:77%;top:79%;transform:translate(-50%,-50%) translateZ(100px) rotateY(-15deg) rotateX(-6deg);width:315px}

.station-glass-card{padding:20px 22px;background:rgba(8,20,32,.82);border:1px solid rgba(130,180,219,.3);border-radius:8px;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);box-shadow:0 18px 50px rgba(0,0,0,.65),inset 0 0 0 1px rgba(255,255,255,.08);transition:all .32s cubic-bezier(.2,1,.3,1)}
.penthouse-station:hover .station-glass-card,.penthouse-station:focus-visible .station-glass-card{border-color:#5ca7e6;background:rgba(12,28,48,.92);box-shadow:0 24px 65px rgba(28,105,212,.4),inset 0 0 18px rgba(92,167,230,.25);transform:scale(1.05) translateZ(30px)}

.station-card-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.station-badge{display:flex;align-items:center;gap:7px;font-size:10px;font-weight:750;letter-spacing:.09em;color:#7dbef5;text-transform:uppercase}
.station-num{font-family:ui-monospace,monospace;font-size:11px;font-weight:600;color:#57748e}
.station-title{margin:0 0 6px;font-size:14px;font-weight:650;color:#fff;letter-spacing:-.01em}
.station-desc{margin:0 0 14px;font-size:11px;color:#9bb1c5;line-height:1.45}
.station-cta{display:inline-flex;align-items:center;gap:7px;font-size:10px;font-weight:750;letter-spacing:.08em;text-transform:uppercase;color:#5ca7e6;padding:6px 12px;background:rgba(28,105,212,.16);border:1px solid rgba(28,105,212,.32);border-radius:4px;transition:all .2s ease}
.penthouse-station:hover .station-cta{background:#1c69d4;color:#fff;border-color:#1c69d4;box-shadow:0 0 14px rgba(28,105,212,.5)}
.cta-arrow{transition:transform .2s ease}
.penthouse-station:hover .cta-arrow{transform:translateX(4px)}

.penthouse-hud-guide{position:absolute;bottom:26px;left:50%;transform:translateX(-50%);z-index:10;display:flex;align-items:center;gap:10px;padding:9px 22px;background:rgba(5,14,24,.88);border:1px solid rgba(130,180,219,.28);border-radius:30px;backdrop-filter:blur(14px);color:#c4dcff;font-size:11px;pointer-events:none;box-shadow:0 10px 32px rgba(0,0,0,.5);letter-spacing:.02em}

/* Active 2D Station Overlay Stage */
.active-station-stage{position:relative;z-index:20;min-height:100vh;animation:stage-fade-in .36s ease-out}
.active-station-stage.hidden{display:none}
@keyframes stage-fade-in{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:scale(1)}}

.station-stage-bar{position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:flex-start;padding:12px 34px;background:rgba(6,15,25,.94);backdrop-filter:blur(18px);border-bottom:1px solid rgba(130,180,219,.2)}
.return-to-penthouse-btn{display:inline-flex;align-items:center;gap:10px;padding:8px 16px;background:rgba(28,105,212,.18);border:1px solid rgba(130,180,219,.4);color:#e1f0ff;border-radius:4px;font-size:11px;font-weight:750;letter-spacing:.07em;text-transform:uppercase;cursor:pointer;transition:all .2s ease}
.return-to-penthouse-btn:hover{background:#1c69d4;color:#fff;border-color:#1c69d4;box-shadow:0 0 18px rgba(28,105,212,.45);transform:translateY(-1px)}
.return-to-penthouse-btn .btn-icon{font-size:14px;transition:transform .2s ease}
.return-to-penthouse-btn:hover .btn-icon{transform:translateX(-3px)}
.return-to-penthouse-btn kbd{padding:2px 6px;background:rgba(0,0,0,.45);border:1px solid rgba(255,255,255,.22);border-radius:3px;font-size:9px;font-family:ui-monospace,monospace;color:#8cbbe8}

@media(max-width:1180px){
  .station-left{left:14%;width:290px}
  .station-right{left:85%;width:290px}
  .station-desk{left:80%;top:82%;width:280px}
}
@media(max-width:900px){
  .penthouse-viewport{perspective:none}
  .penthouse-camera{transform:none!important}
  .penthouse-station{position:relative;left:auto!important;top:auto!important;transform:none!important;width:100%!important;margin-bottom:12px}
  .penthouse-stations-layer{position:relative;display:flex;flex-direction:column;gap:10px;padding:24px;pointer-events:auto;overflow-y:auto;height:100%}
  .penthouse-hud-guide{display:none}
}

