function showView(view) {
  if (view === 'studio') {
    isFlying = true;
    const camera = $('penthouse-camera');
    const viewport = $('penthouse-viewport');
    const stage = $('active-station-stage');
    if (stage) stage.classList.add('hidden');
    if (viewport) viewport.classList.remove('hidden');
    if (camera) {
      camera.style.transition = 'transform 0.85s cubic-bezier(0.22, 1, 0.36, 1)';
      camera.style.transform = 'translate3d(0, 0, 0) rotateY(0deg) rotateX(0deg)';
    }
    setTimeout(() => {
      isFlying = false;
    }, 850);
    currentView = 'studio';
    document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === 'studio'));
    updateStationSummaries();
    return;
  }

  let targetScreen = view;
  if (targetScreen === 'workspace' && !state.config) targetScreen = 'setup';

  isFlying = true;
  const camera = $('penthouse-camera');
  const viewport = $('penthouse-viewport');
  const stage = $('active-station-stage');
  const coords = cameraCoordinates[targetScreen] || cameraCoordinates.workspace;

  if (viewport && viewport.classList.contains('hidden')) {
    viewport.classList.remove('hidden');
  }

  if (camera) {
    camera.style.transition = 'transform 0.8s cubic-bezier(0.22, 1, 0.36, 1)';
    camera.style.transform = `translate3d(${coords.x}px, ${coords.y}px, ${coords.z}px) rotateY(${coords.rotY}deg) rotateX(${coords.rotX}deg)`;
  }

  setTimeout(() => {
    if (viewport) viewport.classList.add('hidden');
    if (stage) stage.classList.remove('hidden');
    ['setup','workspace','memory','market'].forEach(id => $(id)?.classList.add('hidden'));
    $(targetScreen)?.classList.remove('hidden');
    currentView = targetScreen;
    isFlying = false;
    if (targetScreen === 'memory') { setTimeout(() => $('memory-search')?.focus(), 50); }
    else if (targetScreen === 'market') { renderMarketView(); }
    document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === (view === 'setup' ? 'workspace' : view)));
  }, 750);
}

