// Penthouse 3D WebGL Studio & Camera Flight Engine
// Uses Three.js (r128) with zero network dependencies

export class PenthouseStudio {
  constructor(canvas, onStationSelect) {
    this.canvas = canvas;
    this.onStationSelect = onStationSelect;
    this.stations = {};
    this.interactiveMeshes = [];
    this.hoveredStation = null;
    this.isFlying = false;
    this.currentView = 'studio';

    // Camera coordinates for each station
    this.cameraWaypoints = {
      studio: {
        pos: new THREE.Vector3(0, 2.7, 8.5),
        lookAt: new THREE.Vector3(0, 1.6, -1.8)
      },
      setup: {
        pos: new THREE.Vector3(0, 2.0, 1.8),
        lookAt: new THREE.Vector3(0, 2.0, -1.8)
      },
      workspace: {
        pos: new THREE.Vector3(-5.2, 2.9, -0.6),
        lookAt: new THREE.Vector3(-7.2, 2.9, -3.8)
      },
      memory: {
        pos: new THREE.Vector3(5.2, 2.9, -0.6),
        lookAt: new THREE.Vector3(7.2, 2.9, -3.8)
      },
      market: {
        pos: new THREE.Vector3(4.3, 1.9, 3.8),
        lookAt: new THREE.Vector3(5.4, 1.6, 2.3)
      }
    };

    this.currentCamPos = this.cameraWaypoints.studio.pos.clone();
    this.currentCamLook = this.cameraWaypoints.studio.lookAt.clone();
    this.targetCamPos = this.cameraWaypoints.studio.pos.clone();
    this.targetCamLook = this.cameraWaypoints.studio.lookAt.clone();
    this.flightStartPos = new THREE.Vector3();
    this.flightStartLook = new THREE.Vector3();
    this.flightProgress = 1;
    this.flightDuration = 1100; // ms
    this.flightStartTime = 0;

    // Mouse parallax
    this.mouseNorm = { x: 0, y: 0 };
    this.parallaxOffset = new THREE.Vector3();

    this.initScene();
    this.buildPenthouseRoom();
    this.buildCarModel();
    this.buildScreens();
    this.initEvents();
    this.animate(0);
  }

  initScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x04080e);
    this.scene.fog = new THREE.FogExp2(0x04080e, 0.022);

    const aspect = this.canvas.clientWidth / this.canvas.clientHeight || window.innerWidth / window.innerHeight;
    this.camera = new THREE.PerspectiveCamera(52, aspect, 0.1, 100);
    this.camera.position.copy(this.currentCamPos);
    this.camera.lookAt(this.currentCamLook);

    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: 'high-performance'
    });
    this.renderer.setSize(this.canvas.clientWidth, this.canvas.clientHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;

    this.raycaster = new THREE.Raycaster();
    this.mouse = new THREE.Vector2(-999, -999);

    // Ambient & Directional Lights
    const ambientLight = new THREE.AmbientLight(0x101a28, 1.6);
    this.scene.add(ambientLight);

    const mainSpot = new THREE.SpotLight(0xddeeff, 2.4, 30, Math.PI / 4, 0.35, 1);
    mainSpot.position.set(0, 7.5, 2);
    mainSpot.target.position.set(0, 1.2, -1.8);
    this.scene.add(mainSpot);
    this.scene.add(mainSpot.target);

    // Subtle blue showroom accent lights
    const blueSpotLeft = new THREE.PointLight(0x1c69d4, 2.2, 18);
    blueSpotLeft.position.set(-6, 4.5, 0);
    this.scene.add(blueSpotLeft);

    const blueSpotRight = new THREE.PointLight(0x38a9e0, 2.2, 18);
    blueSpotRight.position.set(6, 4.5, 0);
    this.scene.add(blueSpotRight);

    const rimLight = new THREE.DirectionalLight(0x6090c0, 0.8);
    rimLight.position.set(0, 4, -12);
    this.scene.add(rimLight);
  }

  buildPenthouseRoom() {
    // 1. Polished floor with showroom grid
    const floorGeo = new THREE.PlaneGeometry(36, 36, 18, 18);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x090f17,
      roughness: 0.18,
      metalness: 0.72
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0;
    this.scene.add(floor);

    // Floor showroom grid lines
    const gridHelper = new THREE.GridHelper(36, 24, 0x1c4470, 0x0f2238);
    gridHelper.position.y = 0.01;
    this.scene.add(gridHelper);

    // 2. Ceiling with glowing architectural recessed lights
    const ceilingGeo = new THREE.PlaneGeometry(36, 36);
    const ceilingMat = new THREE.MeshStandardMaterial({
      color: 0x070c12,
      roughness: 0.6,
      metalness: 0.3
    });
    const ceiling = new THREE.Mesh(ceilingGeo, ceilingMat);
    ceiling.rotation.x = Math.PI / 2;
    ceiling.position.y = 7.8;
    this.scene.add(ceiling);

    // Glowing LED light strips on ceiling
    for (let x = -8; x <= 8; x += 4) {
      const stripGeo = new THREE.BoxGeometry(0.18, 0.05, 20);
      const stripMat = new THREE.MeshBasicMaterial({ color: 0x8ec7f5 });
      const strip = new THREE.Mesh(stripGeo, stripMat);
      strip.position.set(x, 7.75, -2);
      this.scene.add(strip);
    }

    // 3. Side & back walls
    const wallMat = new THREE.MeshStandardMaterial({ color: 0x060c14, roughness: 0.7 });

    // Left architectural wall with pillars
    const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.6, 8, 36), wallMat);
    leftWall.position.set(-16, 4, 0);
    this.scene.add(leftWall);

    // Right architectural wall
    const rightWall = new THREE.Mesh(new THREE.BoxGeometry(0.6, 8, 36), wallMat);
    rightWall.position.set(16, 4, 0);
    this.scene.add(rightWall);

    // 4. Munich Skyline Panoramic Window at the back (-Z)
    const windowFrameGeo = new THREE.BoxGeometry(32, 7.8, 0.4);
    const windowFrameMat = new THREE.MeshStandardMaterial({ color: 0x0a121c, metalness: 0.8, roughness: 0.3 });
    const windowFrame = new THREE.Mesh(windowFrameGeo, windowFrameMat);
    windowFrame.position.set(0, 3.9, -15);
    this.scene.add(windowFrame);

    // Munich night backdrop canvas texture
    const skylineCanvas = document.createElement('canvas');
    skylineCanvas.width = 1024;
    skylineCanvas.height = 512;
    const sCtx = skylineCanvas.getContext('2d');

    // Night sky gradient (sunset to dark navy)
    const skyGrad = sCtx.createLinearGradient(0, 0, 0, 512);
    skyGrad.addColorStop(0, '#040b15');
    skyGrad.addColorStop(0.5, '#0a1d33');
    skyGrad.addColorStop(0.85, '#243b55');
    skyGrad.addColorStop(1, '#654321');
    sCtx.fillStyle = skyGrad;
    sCtx.fillRect(0, 0, 1024, 512);

    // Distant city silhouette & glowing windows
    sCtx.fillStyle = '#060f1b';
    sCtx.beginPath();
    sCtx.moveTo(0, 512);
    for (let i = 0; i <= 1024; i += 24) {
      const bh = 140 + Math.sin(i * 0.05) * 50 + Math.cos(i * 0.02) * 40;
      sCtx.lineTo(i, 512 - bh);
      sCtx.lineTo(i + 20, 512 - bh);
    }
    sCtx.lineTo(1024, 512);
    sCtx.fill();

    // Iconic Munich Landmarks: Olympiaturm and BMW Four-Cylinder Tower
    // Olympiaturm needle (center-left)
    sCtx.fillStyle = '#040b14';
    sCtx.fillRect(490, 512 - 380, 10, 380);
    sCtx.beginPath();
    sCtx.arc(495, 512 - 320, 22, 0, Math.PI * 2);
    sCtx.fill();
    // Red tower beacon
    sCtx.fillStyle = '#e22718';
    sCtx.beginPath();
    sCtx.arc(495, 512 - 380, 4, 0, Math.PI * 2);
    sCtx.fill();

    // BMW 4-Cylinder Tower (center)
    sCtx.fillStyle = '#0a1a2b';
    sCtx.fillRect(525, 512 - 270, 36, 270);
    sCtx.fillStyle = '#1c69d4';
    sCtx.beginPath();
    sCtx.arc(543, 512 - 276, 8, 0, Math.PI * 2);
    sCtx.fill();

    // Twinkling warm & cyan city lights
    for (let j = 0; j < 300; j++) {
      const lx = Math.random() * 1024;
      const ly = 320 + Math.random() * 180;
      sCtx.fillStyle = Math.random() > 0.3 ? '#ffe082' : '#80d8ff';
      sCtx.globalAlpha = 0.3 + Math.random() * 0.7;
      sCtx.fillRect(lx, ly, 2, 2);
    }
    sCtx.globalAlpha = 1.0;

    const skylineTex = new THREE.CanvasTexture(skylineCanvas);
    const skylineMat = new THREE.MeshBasicMaterial({ map: skylineTex });
    const skylineMesh = new THREE.Mesh(new THREE.PlaneGeometry(31.5, 7.5), skylineMat);
    skylineMesh.position.set(0, 3.9, -14.8);
    this.scene.add(skylineMesh);

    // Glass window mullions
    for (let gx = -12; gx <= 12; gx += 4) {
      const mullion = new THREE.Mesh(new THREE.BoxGeometry(0.12, 7.6, 0.2), windowFrameMat);
      mullion.position.set(gx, 3.9, -14.6);
      this.scene.add(mullion);
    }
  }

  buildCarModel() {
    this.carGroup = new THREE.Group();
    this.carGroup.position.set(0, 0, -2.0);

    // Elevated circular turntable
    const stageGeo = new THREE.CylinderGeometry(3.6, 3.8, 0.14, 48);
    const stageMat = new THREE.MeshStandardMaterial({
      color: 0x081320,
      metalness: 0.85,
      roughness: 0.2
    });
    const stage = new THREE.Mesh(stageGeo, stageMat);
    stage.position.y = 0.07;
    this.carGroup.add(stage);

    // Glowing LED edge ring on the turntable
    const ringGeo = new THREE.RingGeometry(3.55, 3.75, 48);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0x1c69d4, side: THREE.DoubleSide });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.145;
    this.carGroup.add(ring);

    // Procedural Stylized BMW 5 Series / i5 Sedan (Metallic Dark Silver)
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0xb0b8c2,
      metalness: 0.9,
      roughness: 0.18
    });
    const glassMat = new THREE.MeshStandardMaterial({
      color: 0x050a12,
      metalness: 0.95,
      roughness: 0.05,
      transparent: true,
      opacity: 0.75
    });
    const darkTrimMat = new THREE.MeshStandardMaterial({ color: 0x0c0f14, roughness: 0.4 });
    const chromeMat = new THREE.MeshStandardMaterial({ color: 0xe8eef5, metalness: 0.95, roughness: 0.1 });

    // Lower Chassis
    const chassis = new THREE.Mesh(new THREE.BoxGeometry(1.9, 0.45, 4.4), bodyMat);
    chassis.position.y = 0.45;
    this.carGroup.add(chassis);

    // Front Hood & Aerodynamic Nose
    const hood = new THREE.Mesh(new THREE.BoxGeometry(1.82, 0.28, 1.4), bodyMat);
    hood.position.set(0, 0.62, 1.4);
    hood.rotation.x = -0.06;
    this.carGroup.add(hood);

    // Curved Cabin / Greenhouse
    const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.65, 0.58, 2.2), glassMat);
    cabin.position.set(0, 0.95, -0.3);
    this.carGroup.add(cabin);

    // Roof Panel
    const roof = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.06, 1.8), bodyMat);
    roof.position.set(0, 1.25, -0.3);
    this.carGroup.add(roof);

    // Rear Trunk Deck
    const trunk = new THREE.Mesh(new THREE.BoxGeometry(1.78, 0.28, 0.95), bodyMat);
    trunk.position.set(0, 0.65, -1.75);
    trunk.rotation.x = 0.05;
    this.carGroup.add(trunk);

    // Iconic BMW Kidney Grilles (Glowing contour)
    const grilleMat = new THREE.MeshStandardMaterial({ color: 0x090d12, metalness: 0.9 });
    const grilleL = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.26, 0.08), grilleMat);
    grilleL.position.set(-0.25, 0.48, 2.18);
    const grilleR = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.26, 0.08), grilleMat);
    grilleR.position.set(0.25, 0.48, 2.18);
    this.carGroup.add(grilleL);
    this.carGroup.add(grilleR);

    // Glowing Kidney Grille Contour LED
    const glowRingGeo = new THREE.RingGeometry(0.18, 0.23, 16);
    const glowRingMat = new THREE.MeshBasicMaterial({ color: 0x58b4ff, side: THREE.DoubleSide });
    const glowL = new THREE.Mesh(glowRingGeo, glowRingMat);
    glowL.position.set(-0.25, 0.48, 2.23);
    const glowR = new THREE.Mesh(glowRingGeo, glowRingMat);
    glowR.position.set(0.25, 0.48, 2.23);
    this.carGroup.add(glowL);
    this.carGroup.add(glowR);

    // Quad Headlights (Cyan LED)
    const lightMat = new THREE.MeshBasicMaterial({ color: 0xd0f0ff });
    const hl1 = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.09, 0.08), lightMat);
    hl1.position.set(-0.72, 0.52, 2.14);
    const hl2 = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.09, 0.08), lightMat);
    hl2.position.set(0.72, 0.52, 2.14);
    this.carGroup.add(hl1);
    this.carGroup.add(hl2);

    // Rear Lightbar (Red LED)
    const tailMat = new THREE.MeshBasicMaterial({ color: 0xe22718 });
    const tailbar = new THREE.Mesh(new THREE.BoxGeometry(1.68, 0.08, 0.08), tailMat);
    tailbar.position.set(0, 0.62, -2.22);
    this.carGroup.add(tailbar);

    // 4 Aerodynamic Wheels
    const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.26, 24);
    wheelGeo.rotateZ(Math.PI / 2);
    const tireMat = new THREE.MeshStandardMaterial({ color: 0x14171a, roughness: 0.8 });
    const rimMat = new THREE.MeshStandardMaterial({ color: 0xd8e0e8, metalness: 0.9, roughness: 0.2 });

    const wheelPositions = [
      [-0.95, 0.36, 1.4],
      [0.95, 0.36, 1.4],
      [-0.95, 0.36, -1.4],
      [0.95, 0.36, -1.4]
    ];

    wheelPositions.forEach(([wx, wy, wz]) => {
      const wheel = new THREE.Group();
      wheel.position.set(wx, wy, wz);
      const tire = new THREE.Mesh(wheelGeo, tireMat);
      const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.27, 16), rimMat);
      rim.rotation.z = Math.PI / 2;
      wheel.add(tire);
      wheel.add(rim);
      this.carGroup.add(wheel);
    });

    this.scene.add(this.carGroup);
  }

  buildScreens() {
    // Helper to create glowing holographic screen mesh with dynamic canvas texture
    const makeScreen = (name, width, height, drawFn) => {
      const canvas = document.createElement('canvas');
      canvas.width = 1024;
      canvas.height = 512;
      const ctx = canvas.getContext('2d');
      drawFn(ctx, false);

      const texture = new THREE.CanvasTexture(canvas);
      texture.minFilter = THREE.LinearFilter;

      const screenGeo = new THREE.PlaneGeometry(width, height);
      const screenMat = new THREE.MeshBasicMaterial({
        map: texture,
        transparent: true,
        opacity: 0.92,
        side: THREE.DoubleSide
      });

      const screenMesh = new THREE.Mesh(screenGeo, screenMat);

      // Frame / Glass backing
      const frameGeo = new THREE.BoxGeometry(width + 0.08, height + 0.08, 0.04);
      const frameMat = new THREE.MeshStandardMaterial({
        color: 0x081524,
        metalness: 0.9,
        roughness: 0.2,
        transparent: true,
        opacity: 0.7
      });
      const frameMesh = new THREE.Mesh(frameGeo, frameMat);
      frameMesh.position.z = -0.03;
      screenMesh.add(frameMesh);

      // Glowing border ring
      const borderGeo = new THREE.EdgesGeometry(screenGeo);
      const borderMat = new THREE.LineBasicMaterial({ color: 0x38a9e0, linewidth: 2 });
      const borderLines = new THREE.LineSegments(borderGeo, borderMat);
      borderLines.position.z = 0.01;
      screenMesh.add(borderLines);

      screenMesh.userData = {
        name,
        canvas,
        ctx,
        texture,
        drawFn,
        borderMat,
        isHovered: false
      };

      this.interactiveMeshes.push(screenMesh);
      return screenMesh;
    };

    // 1. Station 00: Center Screen (Vehicle Strategy & Setup)
    this.stations.setup = makeScreen('setup', 3.8, 2.0, (ctx, isHover) => {
      ctx.clearRect(0, 0, 1024, 512);
      ctx.fillStyle = isHover ? 'rgba(8, 24, 44, 0.95)' : 'rgba(5, 15, 26, 0.88)';
      ctx.fillRect(0, 0, 1024, 512);

      // Glow border
      ctx.strokeStyle = isHover ? '#58b9ff' : '#1c69d4';
      ctx.lineWidth = isHover ? 8 : 4;
      ctx.strokeRect(4, 4, 1016, 504);

      // Header
      ctx.fillStyle = '#6ab8ff';
