  initEvents() {
    window.addEventListener('resize', () => this.onResize());

    // Raycast click
    this.canvas.addEventListener('click', e => {
      if (this.isFlying) return;
      const rect = this.canvas.getBoundingClientRect();
      this.mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      this.mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

      this.raycaster.setFromCamera(this.mouse, this.camera);
      const intersects = this.raycaster.intersectObjects(this.interactiveMeshes, true);

      if (intersects.length > 0) {
        // Find top-level station mesh
        let hitMesh = intersects[0].object;
        while (hitMesh && !hitMesh.userData.name && hitMesh.parent) {
          hitMesh = hitMesh.parent;
        }
        if (hitMesh && hitMesh.userData.name) {
          this.flyTo(hitMesh.userData.name);
          if (this.onStationSelect) this.onStationSelect(hitMesh.userData.name);
        }
      }
    });

    // Mouse move hover & parallax
    window.addEventListener('mousemove', e => {
      const rect = this.canvas.getBoundingClientRect();
      const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      this.mouse.x = x;
      this.mouse.y = y;

      if (this.currentView === 'studio' && !this.isFlying) {
        this.mouseNorm.x = (e.clientX - window.innerWidth / 2) / (window.innerWidth / 2);
        this.mouseNorm.y = (e.clientY - window.innerHeight / 2) / (window.innerHeight / 2);
      }
    });
  }

  onResize() {
    const width = this.canvas.clientWidth || window.innerWidth;
    const height = this.canvas.clientHeight || window.innerHeight;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height);
  }

  flyTo(stationName) {
    const targetWaypoint = this.cameraWaypoints[stationName];
    if (!targetWaypoint) return;

    this.currentView = stationName;
    this.isFlying = true;
    this.flightStartTime = performance.now();
    this.flightProgress = 0;

    this.flightStartPos.copy(this.camera.position);
    this.flightStartLook.copy(this.currentCamLook);

    this.targetCamPos.copy(targetWaypoint.pos);
    this.targetCamLook.copy(targetWaypoint.lookAt);
  }

  updateHover() {
    if (this.isFlying || this.currentView !== 'studio') {
      if (this.hoveredStation) {
        this.setMeshHover(this.hoveredStation, false);
        this.hoveredStation = null;
        this.canvas.style.cursor = 'default';
      }
      return;
    }

    this.raycaster.setFromCamera(this.mouse, this.camera);
    const intersects = this.raycaster.intersectObjects(this.interactiveMeshes, true);

    let hitStation = null;
    if (intersects.length > 0) {
      let hitMesh = intersects[0].object;
      while (hitMesh && !hitMesh.userData.name && hitMesh.parent) {
        hitMesh = hitMesh.parent;
      }
      if (hitMesh && hitMesh.userData.name) {
        hitStation = hitMesh;
      }
    }

    if (hitStation !== this.hoveredStation) {
      if (this.hoveredStation) this.setMeshHover(this.hoveredStation, false);
      if (hitStation) this.setMeshHover(hitStation, true);
      this.hoveredStation = hitStation;
      this.canvas.style.cursor = hitStation ? 'pointer' : 'default';
    }
  }

  setMeshHover(mesh, isHover) {
    if (!mesh || !mesh.userData) return;
    mesh.userData.isHovered = isHover;
    mesh.userData.drawFn(mesh.userData.ctx, isHover);
    mesh.userData.texture.needsUpdate = true;
    if (mesh.userData.borderMat) {
      mesh.userData.borderMat.color.setHex(isHover ? 0x64c8ff : 0x1c69d4);
    }
  }

  updateTelemetry(config, groupCount, reqCount, eventCount) {
    // Redraw setup screen with live values
    if (this.stations.setup) {
      this.stations.setup.userData.drawFn = (ctx, isHover) => {
        ctx.clearRect(0, 0, 1024, 512);
        ctx.fillStyle = isHover ? 'rgba(8, 24, 44, 0.95)' : 'rgba(5, 15, 26, 0.88)';
        ctx.fillRect(0, 0, 1024, 512);
        ctx.strokeStyle = isHover ? '#58b9ff' : '#1c69d4';
        ctx.lineWidth = isHover ? 8 : 4;
        ctx.strokeRect(4, 4, 1016, 504);

        ctx.fillStyle = '#6ab8ff';
        ctx.font = 'bold 24px Inter, sans-serif';
        ctx.fillText('00 · VEHICLE STRATEGY & PLANNING CONSTRAINTS', 40, 60);

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 38px Inter, sans-serif';
        ctx.fillText(`${config?.vehicle || 'BMW 5 Series (G60)'} Strategy`, 40, 118);

        const metrics = [
          ['TARGET MARKET', config?.market || 'United States · US'],
          ['TIME TO MARKET', `${config?.months || 18} Months Target`],
          ['TEAM CAPACITY', `${config?.people || 12} People Assigned`],
          ['DEADLINE IMPORTANCE', `${config?.importance || 8} / 10 Strategic Priority`]
        ];

        metrics.forEach(([title, val], idx) => {
          const x = 40 + (idx % 2) * 480;
          const y = 170 + Math.floor(idx / 2) * 110;
          ctx.fillStyle = 'rgba(18, 38, 62, 0.7)';
          ctx.fillRect(x, y, 440, 85);
          ctx.strokeStyle = 'rgba(100, 180, 240, 0.3)';
          ctx.lineWidth = 1;
          ctx.strokeRect(x, y, 440, 85);

          ctx.fillStyle = '#8eaac8';
          ctx.font = 'bold 16px Inter, sans-serif';
          ctx.fillText(title, x + 20, y + 32);

          ctx.fillStyle = '#eaf4ff';
          ctx.font = 'bold 22px Inter, sans-serif';
          ctx.fillText(val, x + 20, y + 66);
        });

        ctx.fillStyle = isHover ? '#1c69d4' : '#122e4d';
        ctx.fillRect(40, 410, 944, 65);
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 22px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(isHover ? 'ENTER STRATEGY & VEHICLE CONSTRAINTS →' : 'CLICK TO CONFIGURE VEHICLE STRATEGY', 512, 452);
        ctx.textAlign = 'left';
      };
      this.stations.setup.userData.drawFn(this.stations.setup.userData.ctx, false);
      this.stations.setup.userData.texture.needsUpdate = true;
    }
  }

  animate(time) {
    requestAnimationFrame(t => this.animate(t));

    // Flight interpolation
    if (this.isFlying) {
      const elapsed = time - this.flightStartTime;
      const progress = Math.min(1, elapsed / this.flightDuration);

      // Cubic easing
      const ease = progress < 0.5 
        ? 4 * progress * progress * progress 
        : 1 - Math.pow(-2 * progress + 2, 3) / 2;

      this.camera.position.lerpVectors(this.flightStartPos, this.targetCamPos, ease);
      this.currentCamLook.lerpVectors(this.flightStartLook, this.targetCamLook, ease);
      this.camera.lookAt(this.currentCamLook);

      if (progress >= 1) {
        this.isFlying = false;
        this.camera.position.copy(this.targetCamPos);
        this.currentCamLook.copy(this.targetCamLook);
        this.camera.lookAt(this.currentCamLook);
      }
    } else if (this.currentView === 'studio') {
      // Idle slow turntable rotation
      if (this.carGroup) {
        this.carGroup.rotation.y = Math.sin(time * 0.0003) * 0.12;
      }

      // Parallax smooth interpolation
      const targetOffX = this.mouseNorm.x * 0.45;
      const targetOffY = -this.mouseNorm.y * 0.25;
      this.parallaxOffset.x += (targetOffX - this.parallaxOffset.x) * 0.05;
      this.parallaxOffset.y += (targetOffY - this.parallaxOffset.y) * 0.05;

      const idleCamPos = this.cameraWaypoints.studio.pos.clone().add(this.parallaxOffset);
      this.camera.position.copy(idleCamPos);
      this.camera.lookAt(this.cameraWaypoints.studio.lookAt);
    }

    this.updateHover();
    this.renderer.render(this.scene, this.camera);
  }
}

