import { buildModel, draftEmail, gmailComposeUrl, validateCitations } from './engine.js';
import { PenthouseStudio } from './penthouse-3d.js';

const state = { evidence: [], context: null, historical: [], groups: [], selected: 0, config: null, statuses: JSON.parse(localStorage.getItem('requirement-statuses') || '{}'), overrides: JSON.parse(localStorage.getItem('requirement-overrides') || '{}'), events: JSON.parse(localStorage.getItem('decision-events') || '[]'), activeRequirement: null, openAIConfigured:false, marketInsights:null };
const $ = id => document.getElementById(id);
const escapeHtml = value => String(value).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusKey = feature => `${state.config.vehicle}|${state.config.market}|${feature}`;
const statusMap = () => Object.fromEntries(Object.entries(state.statuses).filter(([key]) => key.startsWith(`${state.config?.vehicle || 'G60'}|${state.config?.market || 'US'}|`)).map(([key,value]) => [key.split('|').slice(2).join('|'),value==='awaiting'?'not-checked':value]));
const overrideMap = () => Object.fromEntries(Object.entries(state.overrides).filter(([key]) => key.startsWith(`${state.config?.vehicle || 'G60'}|${state.config?.market || 'US'}|`)).map(([key,value]) => [key.split('|').slice(2).join('|'),value]));

let currentView = 'studio';
let isFlying = false;
let studio = null;

function updateStationSummaries() {
  const v = $('vehicle')?.value || 'G60';
  const m = $('market')?.value || 'US';
  const mo = $('months')?.value || '18';
  const p = $('people')?.value || '12';
  const imp = $('importance')?.value || '8';
  if ($('station-setup-summary')) {
    $('station-setup-summary').textContent = `${v} · ${m} · ${mo} Mo · ${p} People · Deadline ${imp}/10`;
  }
  if ($('station-workspace-summary')) {
    const totalReqs = state.groups?.reduce((sum, g) => sum + g.requirements.length, 0) || 0;
    $('station-workspace-summary').textContent = `${state.groups?.length || 4} Domains · ${totalReqs ? totalReqs + ' Requirements' : 'Ready to evaluate'}`;
  }
  if ($('station-memory-summary')) {
    const count = (state.events?.length || 0) + (state.historical?.length || 0);
    $('station-memory-summary').textContent = `${count} Total Decision Records · Append-Only Memory`;
  }
  if ($('station-market-summary')) {
    $('station-market-summary').textContent = `Target: ${v} · ${m} · Verified Competitor Benchmarks`;
  }
  if (studio) {
    const totalReqs = state.groups?.reduce((sum, g) => sum + g.requirements.length, 0) || 0;
    const count = (state.events?.length || 0) + (state.historical?.length || 0);
    studio.updateTelemetry({ vehicle: v, market: m, months: mo, people: p, importance: imp }, state.groups?.length, totalReqs, count);
  }
}

async function init() {
  initOrbitSweepGradient();

  const canvas = $('studio-canvas');
  if (canvas && window.THREE) {
    studio = new PenthouseStudio(canvas, station => {
      showView(station);
    });
  }

  $('importance').addEventListener('input', e => { $('importance-output').value = `${e.target.value} / 10`; updateStationSummaries(); });
  $('vehicle').addEventListener('change', () => { populateMarkets(); updateStationSummaries(); });
  $('market').addEventListener('change', updateStationSummaries);
  $('months').addEventListener('input', updateStationSummaries);
  $('people').addEventListener('input', updateStationSummaries);
  $('config-form').addEventListener('submit', event => { event.preventDefault(); if (state.evidence.length) generate(); });
  $('edit-config').addEventListener('click', () => showView('setup'));
  $('rename-group').addEventListener('click', renameGroup);
  $('recalibrate-group').addEventListener('click', () => recalibrateGroup(state.groups[state.selected]?.name, 'PM requested a fresh ranking'));
  $('split-group').addEventListener('click', splitGroup);
  $('merge-group').addEventListener('click', mergeGroup);
  document.querySelectorAll('.nav').forEach(b => b.addEventListener('click', () => showView(b.dataset.view)));
  document.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', () => b.closest('dialog')?.close()));
  document.querySelectorAll('[data-report]').forEach(b=>b.addEventListener('click',()=>downloadReport(b.dataset.report)));
  $('memory-search').addEventListener('input',e=>renderMemory(e.target.value));
  $('generate-market-insights').addEventListener('click',generateMarketInsights);
  $('return-to-penthouse')?.addEventListener('click', () => showView('studio'));
  $('brand-home')?.addEventListener('click', e => { e.preventDefault(); showView('studio'); });

  document.querySelectorAll('[data-station]').forEach(station => {
    station.addEventListener('click', () => showView(station.dataset.station));
    station.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        showView(station.dataset.station);
      }
    });
  });

  window.addEventListener('keydown', e => {
    if (e.key === 'Escape') {
      const dialogOpen = document.querySelector('dialog[open]');
      if (dialogOpen) return;
      if (currentView !== 'studio') {
        showView('studio');
      }
    }
  });

  await loadDecisionEvents();
  renderMemory();
  await checkOpenAIStatus();
  const [response,contextResponse,historyResponse] = await Promise.all([fetch('../data/evidence.json'),fetch('../data/context.json'),fetch('../data/historical-decisions.json')]);
  if (!response.ok || !contextResponse.ok || !historyResponse.ok) throw new Error(`Evidence stores failed to load. Start PM with “node server.mjs” from the repository root.`);
  const [payload,context,history] = await Promise.all([response.json(),contextResponse.json(),historyResponse.json()]);
  state.evidence = payload.records;
  state.context = context;
  state.historical = history.decisions.map(decision=>({id:decision.id,type:'historical-decision',title:decision.requirement,description:`${decision.productCycle} · ${decision.decisionStatus}. ${decision.pmReasoning}`,data:decision,actor:'Prior-cycle PM',at:decision.timestamp,provenance:decision.provenance}));
  renderMemory();
  populateMarkets();
  updateStationSummaries();
  $('generate-button').disabled = false;
  $('generate-button').innerHTML = '<span class="shiny-label">Generate evidence-backed requirements <span class="shiny-arrow" aria-hidden="true">→</span></span>';
  showView('studio');
}

