function showView(view) {
  if (view === 'studio') {
    isFlying = true;
    const stage = $('active-station-stage');
    const viewport = $('penthouse-viewport');

    // Immediately hide the docked 2D stage to reveal the 3D room
    if (stage) stage.classList.add('hidden');
    if (viewport) viewport.classList.remove('hidden');

    // Fly camera backwards through 3D room to panoramic studio vantage point
    if (studio) {
      studio.flyTo('studio', () => {
        isFlying = false;
      });
    } else {
      isFlying = false;
    }

    currentView = 'studio';
    document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === 'studio'));
    updateStationSummaries();
    return;
  }

  let targetScreen = view;
  if (targetScreen === 'workspace' && !state.config) targetScreen = 'setup';

  isFlying = true;
  const stage = $('active-station-stage');
  const viewport = $('penthouse-viewport');

  if (viewport && viewport.classList.contains('hidden')) {
    viewport.classList.remove('hidden');
  }
  // While traveling through 3D room, keep 2D stage hidden so user sees 3D flight
  if (stage) stage.classList.add('hidden');

  if (studio) {
    studio.flyTo(targetScreen, () => {
      dockStationView(targetScreen);
    });
  } else {
    dockStationView(targetScreen);
  }
}

function dockStationView(targetScreen) {
  const stage = $('active-station-stage');
  if (stage) stage.classList.remove('hidden');

  ['setup','workspace','memory','market'].forEach(id => $(id)?.classList.add('hidden'));
  $(targetScreen)?.classList.remove('hidden');
  currentView = targetScreen;
  isFlying = false;

  const titleMap = {
    setup: '00 · BMW Vehicle Strategy & Planning Constraints',
    workspace: '01 · Agile Requirements Workspace',
    memory: '02 · Append-Only Decision Memory',
    market: '03 · Executive Competitor Radar'
  };
  if ($('dock-title')) {
    $('dock-title').textContent = titleMap[targetScreen] || targetScreen;
  }

  if (targetScreen === 'memory') {
    setTimeout(() => $('memory-search')?.focus(), 50);
  } else if (targetScreen === 'market') {
    renderMarketView();
  }
  document.querySelectorAll('.nav').forEach(n => n.classList.toggle('active', n.dataset.view === (targetScreen === 'setup' ? 'workspace' : targetScreen)));
}

