args.ReplacementContent:
/* 3D Penthouse Studio Spatial Navigation */
.penthouse-viewport{position:fixed;inset:0;left:228px;width:calc(100vw - 228px);height:100vh;overflow:hidden;background:#04080e;z-index:1;display:flex;align-items:center;justify-content:center}
.penthouse-viewport.hidden{display:none}

.studio-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}

.penthouse-hud-guide{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);z-index:10;display:flex;align-items:center;gap:10px;padding:9px 24px;background:rgba(5,14,24,.88);border:1px solid rgba(130,180,219,.3);border-radius:30px;backdrop-filter:blur(16px);color:#c4dcff;font-size:11px;pointer-events:none;box-shadow:0 10px 32px rgba(0,0,0,.6);letter-spacing:.02em;white-space:nowrap}

.penthouse-quick-hud{position:absolute;bottom:72px;left:50%;transform:translateX(-50%);z-index:10;display:flex;align-items:center;gap:10px;pointer-events:auto}
.quick-station-pill{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;background:rgba(8,20,34,.85);border:1px solid rgba(130,180,219,.32);border-radius:24px;backdrop-filter:blur(14px);color:#dce7f2;font-size:11px;font-weight:650;cursor:pointer;transition:all .22s ease;box-shadow:0 6px 20px rgba(0,0,0,.45)}
.quick-station-pill:hover{background:rgba(28,105,212,.35);border-color:#5ca7e6;color:#fff;transform:translateY(-2px);box-shadow:0 10px 24px rgba(28,105,212,.4)}
.quick-station-pill .pill-num{font-family:ui-monospace,monospace;font-size:10px;color:#7dbef5;font-weight:700}
.quick-station-pill .pill-title{letter-spacing:.02em}

/* Active 2D Station Overlay Stage */
.active-station-stage{position:relative;z-index:20;min-height:100vh;background:rgba(5,14,24,.96);backdrop-filter:blur(30px);-webkit-backdrop-filter:blur(30px);animation:stage-fade-in .36s ease-out;box-shadow:0 0 80px rgba(0,0,0,.85)}
.active-station-stage.hidden{display:none}
@keyframes stage-fade-in{from{opacity:0;transform:scale(.98)}to{opacity:1;transform:scale(1)}}

.station-stage-bar{position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:space-between;padding:14px 34px;background:rgba(6,15,25,.96);backdrop-filter:blur(20px);border-bottom:1px solid rgba(130,180,219,.22)}
.return-to-penthouse-btn{display:inline-flex;align-items:center;gap:10px;padding:8px 18px;background:rgba(28,105,212,.2);border:1px solid rgba(130,180,219,.42);color:#e1f0ff;border-radius:4px;font-size:11px;font-weight:750;letter-spacing:.07em;text-transform:uppercase;cursor:pointer;transition:all .2s ease}
.return-to-penthouse-btn:hover{background:#1c69d4;color:#fff;border-color:#1c69d4;box-shadow:0 0 20px rgba(28,105,212,.5);transform:translateY(-1px)}
.return-to-penthouse-btn .btn-icon{font-size:14px;transition:transform .2s ease}
.return-to-penthouse-btn:hover .btn-icon{transform:translateX(-3px)}
