initScene() {
  this.scene = new THREE.Scene();
  this.scene.background = new THREE.Color(0x03060a);
  this.scene.fog = new THREE.FogExp2(0x03060a, 0.018);

  const aspect = this.canvas.clientWidth / this.canvas.clientHeight || window.innerWidth / window.innerHeight;
  this.camera = new THREE.PerspectiveCamera(52, aspect, 0.1, 100);
  this.camera.position.copy(this.currentCamPos);
  this.camera.lookAt(this.currentCamLook);

  this.renderer = new THREE.WebGLRenderer({
    canvas: this.canvas,
    antialias: true,
    powerPreference: 'high-performance'
  });
  this.renderer.setSize(this.canvas.clientWidth, this.canvas.clientHeight);
  this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
  this.renderer.toneMappingExposure = 1.15;

  this.raycaster = new THREE.Raycaster();
  this.mouse = new THREE.Vector2(-999, -999);

  // Multi-point Showroom Lighting
  const ambientLight = new THREE.AmbientLight(0x0d1724, 2.0);
  this.scene.add(ambientLight);

  // Key overhead spot
  const mainSpot = new THREE.SpotLight(0xddeeff, 2.8, 32, Math.PI / 4, 0.4, 1.2);
  mainSpot.position.set(0, 7.8, 1.5);
  mainSpot.target.position.set(0, 1.0, -2.0);
  this.scene.add(mainSpot);
  this.scene.add(mainSpot.target);

  // Front-left and front-right showroom fill spots
  const fillL = new THREE.SpotLight(0xaad4ff, 1.8, 24, Math.PI / 4, 0.5, 1.2);
  fillL.position.set(-5, 6, 4);
  fillL.target.position.set(0, 0.8, -2.0);
  this.scene.add(fillL);
  this.scene.add(fillL.target);

  const fillR = new THREE.SpotLight(0xaad4ff, 1.8, 24, Math.PI / 4, 0.5, 1.2);
  fillR.position.set(5, 6, 4);
  fillR.target.position.set(0, 0.8, -2.0);
  this.scene.add(fillR);
  this.scene.add(fillR.target);

  // BMW Iconic Blue showroom accents
  const blueSpotLeft = new THREE.PointLight(0x1c69d4, 2.8, 22);
  blueSpotLeft.position.set(-8, 4.5, 0);
  this.scene.add(blueSpotLeft);

  const blueSpotRight = new THREE.PointLight(0x38a9e0, 2.8, 22);
  blueSpotRight.position.set(8, 4.5, 0);
  this.scene.add(blueSpotRight);

  // Horizon & rim backlights
  const rimLight = new THREE.DirectionalLight(0x4070a0, 1.1);
  rimLight.position.set(0, 5, -14);
  this.scene.add(rimLight);
}

buildPenthouseRoom() {
  // 1. Polished Italian Terrazzo / Graphite Marble Floor
  const floorCanvas = document.createElement('canvas');
  floorCanvas.width = 1024;
  floorCanvas.height = 1024;
  const fCtx = floorCanvas.getContext('2d');

  // Deep dark graphite base
  fCtx.fillStyle = '#060a11';
  fCtx.fillRect(0, 0, 1024, 1024);

  // Large showroom tile seams
  fCtx.strokeStyle = 'rgba(28, 68, 114, 0.35)';
  fCtx.lineWidth = 3;
  fCtx.strokeRect(2, 2, 1020, 1020);
  fCtx.beginPath();
  fCtx.moveTo(512, 0); fCtx.lineTo(512, 1024);
  fCtx.moveTo(0, 512); fCtx.lineTo(1024, 512);
  fCtx.stroke();

  // Specular grain and fine terrazzo flecks
  fCtx.fillStyle = 'rgba(140, 190, 240, 0.05)';
  for (let i = 0; i < 500; i++) {
    fCtx.fillRect(Math.random() * 1024, Math.random() * 1024, Math.random() * 2 + 1, Math.random() * 2 + 1);
  }

  const floorTex = new THREE.CanvasTexture(floorCanvas);
  floorTex.wrapS = THREE.RepeatWrapping;
  floorTex.wrapT = THREE.RepeatWrapping;
  floorTex.repeat.set(6, 6);

  const floorGeo = new THREE.PlaneGeometry(42, 42, 12, 12);
  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex,
    color: 0x090f18,
    roughness: 0.12,
    metalness: 0.88
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = 0;
  this.scene.add(floor);

  // Subtle showroom floor grid
  const gridHelper = new THREE.GridHelper(36, 18, 0x1c4470, 0x0c1e33);
  gridHelper.position.y = 0.01;
  this.scene.add(gridHelper);

  // 2. Ceiling with glowing architectural recessed lights
  const ceilingGeo = new THREE.PlaneGeometry(42, 42);
  const ceilingMat = new THREE.MeshStandardMaterial({
    color: 0x05090f,
    roughness: 0.5,
    metalness: 0.4
  });
  const ceiling = new THREE.Mesh(ceilingGeo, ceilingMat);
  ceiling.rotation.x = Math.PI / 2;
  ceiling.position.y = 8.0;
  this.scene.add(ceiling);

  // Suspended luxury showroom halo light ring directly above turntable
  const haloGeo = new THREE.TorusGeometry(3.6, 0.045, 16, 64);
  const haloMat = new THREE.MeshBasicMaterial({ color: 0xe6f4ff });
  const halo = new THREE.Mesh(haloGeo, haloMat);
  halo.rotation.x = Math.PI / 2;
  halo.position.set(0, 6.4, -2.0);
  this.scene.add(halo);

  // Downlight from halo fixture
  const haloSpot = new THREE.SpotLight(0xddeeff, 2.6, 16, Math.PI / 3, 0.4, 1.2);
  haloSpot.position.set(0, 6.3, -2.0);
  haloSpot.target.position.set(0, 0.1, -2.0);
  this.scene.add(haloSpot);
  this.scene.add(haloSpot.target);

  // Glowing linear LED light strips on ceiling
  for (let x = -10; x <= 10; x += 5) {
    const stripGeo = new THREE.BoxGeometry(0.18, 0.06, 24);
    const stripMat = new THREE.MeshBasicMaterial({ color: 0x8ec7f5 });
    const strip = new THREE.Mesh(stripGeo, stripMat);
    strip.position.set(x, 7.95, -2);
    this.scene.add(strip);
  }

  // 3. Side & back architectural columns with blue LED light conduits
  const wallMat = new THREE.MeshStandardMaterial({ color: 0x050b12, roughness: 0.6, metalness: 0.5 });

  // Left & Right architectural perimeter walls
  const leftWall = new THREE.Mesh(new THREE.BoxGeometry(0.8, 8.2, 40), wallMat);
  leftWall.position.set(-18, 4.1, 0);
  this.scene.add(leftWall);

  const rightWall = new THREE.Mesh(new THREE.BoxGeometry(0.8, 8.2, 40), wallMat);
  rightWall.position.set(18, 4.1, 0);
  this.scene.add(rightWall);

  // Showroom architectural pillars with vertical LED accent bars
  const pillarPositions = [
    [-14, -8], [-14, 0], [-14, 8],
    [14, -8], [14, 0], [14, 8]
  ];
  pillarPositions.forEach(([px, pz]) => {
    const col = new THREE.Mesh(
      new THREE.BoxGeometry(0.85, 8.2, 0.85),
      new THREE.MeshStandardMaterial({ color: 0x08121e, metalness: 0.85, roughness: 0.25 })
    );
    col.position.set(px, 4.1, pz);
    this.scene.add(col);

    // Inset vertical cyan LED accent bar
    const ledBar = new THREE.Mesh(
      new THREE.BoxGeometry(0.08, 7.0, 0.08),
      new THREE.MeshBasicMaterial({ color: 0x38a9e0 })
    );
    ledBar.position.set(px > 0 ? px - 0.45 : px + 0.45, 4.1, pz);
    this.scene.add(ledBar);
  });

  // 4. Munich Skyline Panoramic Window at the back (-Z)
  const windowFrameGeo = new THREE.BoxGeometry(36, 8.0, 0.5);
  const windowFrameMat = new THREE.MeshStandardMaterial({ color: 0x07101a, metalness: 0.9, roughness: 0.2 });
  const windowFrame = new THREE.Mesh(windowFrameGeo, windowFrameMat);
  windowFrame.position.set(0, 4.0, -16);
  this.scene.add(windowFrame);

  // High-resolution Munich night backdrop canvas texture (2048x1024)
  const skylineCanvas = document.createElement('canvas');
  skylineCanvas.width = 2048;
  skylineCanvas.height = 1024;
  const sCtx = skylineCanvas.getContext('2d');

  // Rich twilight sky gradient (deep zenith to Munich city horizon)
  const skyGrad = sCtx.createLinearGradient(0, 0, 0, 1024);
  skyGrad.addColorStop(0, '#020509');
  skyGrad.addColorStop(0.4, '#061220');
  skyGrad.addColorStop(0.75, '#12253d');
  skyGrad.addColorStop(0.92, '#203348');
  skyGrad.addColorStop(1, '#2c352d');
  sCtx.fillStyle = skyGrad;
  sCtx.fillRect(0, 0, 2048, 1024);

  // Clear night sky stars
  sCtx.fillStyle = '#ffffff';
  for (let s = 0; s < 350; s++) {
    const sx = Math.random() * 2048;
    const sy = Math.random() * 550;
    sCtx.globalAlpha = 0.2 + Math.random() * 0.8;
    sCtx.fillRect(sx, sy, Math.random() > 0.8 ? 2 : 1, Math.random() > 0.8 ? 2 : 1);
  }
  sCtx.globalAlpha = 1.0;

  // Distant layered skyline silhouettes
  sCtx.fillStyle = '#050c16';
  sCtx.beginPath();
  sCtx.moveTo(0, 1024);
  for (let i = 0; i <= 2048; i += 32) {
    const bh = 260 + Math.sin(i * 0.03) * 90 + Math.cos(i * 0.015) * 60;
    sCtx.lineTo(i, 1024 - bh);
    sCtx.lineTo(i + 26, 1024 - bh);
  }
  sCtx.lineTo(2048, 1024);
  sCtx.fill();

  // Foreground sharper skyscrapers
  sCtx.fillStyle = '#081422';
  sCtx.beginPath();
  sCtx.moveTo(0, 1024);
  for (let i = 0; i <= 2048; i += 48) {
    const bh = 180 + Math.sin(i * 0.04) * 80 + Math.cos(i * 0.02) * 50;
    sCtx.lineTo(i, 1024 - bh);
    sCtx.lineTo(i + 38, 1024 - bh);
  }
  sCtx.lineTo(2048, 1024);
  sCtx.fill();

  // Landmark 1: Munich Olympiaturm (Tower needle & observation decks)
  sCtx.fillStyle = '#07101c';
  sCtx.fillRect(960, 1024 - 720, 16, 720);
  // Lower observation deck
  sCtx.beginPath();
  sCtx.arc(968, 1024 - 600, 38, 0, Math.PI * 2);
  sCtx.fill();
  // Upper antenna deck
  sCtx.beginPath();
  sCtx.arc(968, 1024 - 670, 22, 0, Math.PI * 2);
  sCtx.fill();
  // Illuminated deck window rings
  sCtx.strokeStyle = '#ffd699';
  sCtx.lineWidth = 3;
  sCtx.stroke();
  // Blinking red aviation warning beacon
  sCtx.fillStyle = '#e22718';
  sCtx.beginPath();
  sCtx.arc(968, 1024 - 725, 6, 0, Math.PI * 2);
  sCtx.fill();

  // Landmark 2: Iconic BMW Four-Cylinder Global Headquarters ("Vierzylinder")
  sCtx.fillStyle = '#091829';
  // 4 vertical interconnected cylinders
  sCtx.fillRect(1040, 1024 - 520, 68, 520);
  // Illuminated office floor rings
  sCtx.fillStyle = 'rgba(255, 230, 170, 0.4)';
  for (let f = 1024 - 500; f < 1024 - 100; f += 22) {
    sCtx.fillRect(1042, f, 64, 4);
  }
  // Glowing BMW Blue Roundel crown
  sCtx.fillStyle = '#1c69d4';
  sCtx.beginPath();
  sCtx.arc(1074, 1024 - 530, 14, 0, Math.PI * 2);
  sCtx.fill();
  sCtx.strokeStyle = '#ffffff';
  sCtx.lineWidth = 2;
  sCtx.stroke();

  // Twinkling warm & cyan city lights
  for (let j = 0; j < 600; j++) {
    const lx = Math.random() * 2048;
    const ly = 620 + Math.random() * 380;
    sCtx.fillStyle = Math.random() > 0.35 ? '#ffe6aa' : '#7ed2ff';
    sCtx.globalAlpha = 0.3 + Math.random() * 0.7;
    sCtx.fillRect(lx, ly, 2, 2);
  }
  sCtx.globalAlpha = 1.0;

  const skylineTex = new THREE.CanvasTexture(skylineCanvas);
  const skylineMat = new THREE.MeshBasicMaterial({ map: skylineTex });
  const skylineMesh = new THREE.Mesh(new THREE.PlaneGeometry(35.5, 7.8), skylineMat);
  skylineMesh.position.set(0, 4.0, -15.8);
  this.scene.add(skylineMesh);

  // Glass window structural mullions
  for (let gx = -15; gx <= 15; gx += 5) {
    const mullion = new THREE.Mesh(new THREE.BoxGeometry(0.14, 7.9, 0.25), windowFrameMat);
    mullion.position.set(gx, 4.0, -15.6);
    this.scene.add(mullion);
  }
}

