  // 4. Munich Skyline Panoramic Cylinder Wrapping Behind the Penthouse
  const panoramaGeo = new THREE.CylinderGeometry(32, 32, 18, 64, 1, true, -Math.PI * 0.9, Math.PI * 1.8);
  const skylineMat = new THREE.MeshBasicMaterial({
    map: skylineTex,
    side: THREE.BackSide,
    fog: false,
    depthWrite: false
  });
  const skylineMesh = new THREE.Mesh(panoramaGeo, skylineMat);
  skylineMesh.position.set(0, 6.0, -2.0);
  this.scene.add(skylineMesh);

  // Floor-to-ceiling panoramic showroom glass curtain wall
  const glassMat = new THREE.MeshStandardMaterial({
    color: 0x061424,
    transparent: true,
    opacity: 0.22,
    roughness: 0.08,
    metalness: 0.92
  });
  const glassPane = new THREE.Mesh(new THREE.PlaneGeometry(36, 7.8), glassMat);
  glassPane.position.set(0, 4.0, -15.5);
  this.scene.add(glassPane);

  // Structural dark architectural window mullions
  const windowFrameMat = new THREE.MeshStandardMaterial({ color: 0x07101a, metalness: 0.9, roughness: 0.2 });
  for (let gx = -16; gx <= 16; gx += 4) {
    const mullion = new THREE.Mesh(new THREE.BoxGeometry(0.12, 7.9, 0.18), windowFrameMat);
    mullion.position.set(gx, 4.0, -15.4);
    this.scene.add(mullion);
  }

  // Top and bottom architectural window sills
  const topSill = new THREE.Mesh(new THREE.BoxGeometry(36, 0.2, 0.3), windowFrameMat);
  topSill.position.set(0, 7.9, -15.4);
  this.scene.add(topSill);

  const bottomSill = new THREE.Mesh(new THREE.BoxGeometry(36, 0.2, 0.3), windowFrameMat);
  bottomSill.position.set(0, 0.1, -15.4);
  this.scene.add(bottomSill);
}

